import {esc} from './paper-render.js?v=word-format-20261120';
import {NOTE_SOURCES,noteSource} from './notebook-core.js?v=geometry-20261119';
import {shapes,lineStyles} from './paper-shapes.js?v=notebook-shape-tools-20261120';
import {PEN_WIDTH_PRESETS} from './paper-core.js?v=word-format-20261120';
export const colors=['#172033','#3155d9','#15966d','#dc4343','#8756c6','#ef9e39'];
const icons={select:'↖',pen:'✎',highlight:'▰',eraser:'◇',text:'T',shape:'△',image:'▧',hand:'✋',undo:'↶',redo:'↷'};
export function paperPage(space,n){return `<section class="paper-app" aria-label="สมุดกระดาษ"><header class="paper-header"><a class="paper-back" href="#notes" aria-label="กลับสมุดจด">‹</a><div class="paper-heading"><span class="paper-eyebrow">MY NOTEBOOK <span> / ${esc(n.course||'ทั่วไป')}</span></span><input id="paper-title" aria-label="ชื่อโน้ต" maxlength="160" value="${esc(n.title)}"><span class="paper-cloud" data-sync-status role="status">${esc(space.info().status)}</span></div><button class="paper-save" data-paper="save">บันทึกงาน</button><details class="paper-menu"><summary aria-label="ตัวเลือกโน้ต">•••</summary><div><button data-action="nb-pin" data-id="${n.id}">${n.pinned?'เลิกปักหมุด':'ปักหมุดโน้ต'}</button><button data-action="nb-archive" data-id="${n.id}">${n.archived?'นำกลับมาใช้':'เก็บเข้าคลัง'}</button><button data-action="nb-print">พิมพ์หน้านี้</button><button data-action="nb-export">สำรองโน้ตพร้อมรูป</button><button data-paper="legacy">ดูต้นฉบับเดิม</button><button data-action="nb-delete" data-id="${n.id}" class="paper-danger">ลบโน้ต</button></div></details></header>
 <div class="paper-toolbar"><div class="paper-toolset" role="group" aria-label="เครื่องมือจด">${Object.entries(icons).map(([key,icon])=>`<button type="button" data-paper="${key}" aria-label="${({select:'เลือกและย้าย',pen:'ปากกา',highlight:'ไฮไลต์',eraser:'ยางลบ',text:'ข้อความ',shape:'รูปทรง',image:'แทรกรูป',hand:'เลื่อนกระดาษ',undo:'ย้อนกลับ',redo:'ทำซ้ำ'})[key]}" title="${key}"><span>${icon}</span><small>${({select:'เลือก',pen:'ปากกา',highlight:'ไฮไลต์',eraser:'ลบเส้น',text:'ข้อความ',shape:'รูปทรง',image:'รูป',hand:'เลื่อน',undo:'ย้อนกลับ',redo:'ทำซ้ำ'})[key]}</small></button>`).join('')}</div><details class="paper-toolbar-more" id="paper-toolbar-more"><summary aria-label="ตัวเลือกเพิ่มเติมของเครื่องมือจด" title="ตั้งค่าสี ขนาดเส้น ไม้บรรทัด และอื่น ๆ">⚙️ <span>ตัวเลือก</span></summary><div class="paper-tool-options"><button data-paper="multi" aria-pressed="false" title="Shift + คลิก เพื่อเพิ่มหรือเอาออกจากกลุ่ม">เลือกหลายชิ้น</button><details class="paper-geometry-menu" id="paper-geometry-menu"><summary>▱ เส้น/รูปทรง</summary><div class="paper-geometry-options"><label id="paper-shape-options" hidden>รูปทรง <select id="paper-shape">${Object.entries(shapes).map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></label><label id="paper-line-options" hidden>ลักษณะเส้น <select id="paper-line-style">${Object.entries(lineStyles).map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></label><label class="paper-geometry-check"><input id="paper-smart-shape" type="checkbox" checked> วาดแล้วค้าง 0.5 วินาที เพื่อจัดรูปทรง</label><div class="paper-ruler-buttons"><button type="button" data-paper="ruler" aria-pressed="false">📏 เปิดไม้บรรทัด</button><button type="button" data-paper="ruler-minus" aria-label="หมุนไม้บรรทัดทวนเข็มนาฬิกา 15 องศา">↶ 15°</button><button type="button" data-paper="ruler-plus" aria-label="หมุนไม้บรรทัดตามเข็มนาฬิกา 15 องศา">↷ 15°</button><button type="button" data-paper="ruler-zero" aria-label="ตั้งไม้บรรทัดแนวนอน">0°</button></div><p>ใช้จุดกลางย้ายไม้บรรทัด • จุดปลายหมุน • ปากกาเขียนชิดขอบจะได้เส้นตรง</p></div></details><div class="paper-colors" aria-label="สี">${colors.map(c=>`<button data-paper-color="${c}" style="--ink:${c}" aria-label="สี ${c}"></button>`).join('')}</div><div class="paper-pen-sizes" role="group" aria-label="เลือกขนาดเส้น"><button type="button" class="paper-size-toggle" data-paper-size-toggle="true" aria-expanded="false" aria-controls="paper-size-controls" title="เลือกขนาดเส้นปากกา">✎ เส้น <span id="paper-width-mobile-value">5</span> ▾</button><div class="paper-size-controls" id="paper-size-controls"><span class="paper-size-label" id="paper-size-label">ความหนาปากกา (1 = บาง · 12 = หนา) · เลือกจุดหรือเลื่อนแถบได้</span><div class="paper-size-presets">${PEN_WIDTH_PRESETS.map(v=>`<button type="button" class="paper-size-preset" data-paper-width="${v}" aria-label="เส้นขนาด ${v}" title="เส้นขนาด ${v}" aria-pressed="${v===5}"><span style="width:${Math.max(3,v+2)}px;height:${Math.max(3,v+2)}px"></span></button>`).join('')}</div><label class="paper-size-slider" for="paper-width"><span class="sr-only">ปรับขนาดเส้นละเอียด</span><input id="paper-width" aria-label="ปรับความหนาของเส้น" type="range" min="1" max="12" step="1" value="5"></label><output id="paper-width-value" for="paper-width" aria-live="polite">5</output><span class="paper-pen-preview" title="ตัวอย่างความหนาของเส้น"><i id="paper-pen-preview" style="width:5px;height:5px"></i></span></div></div><label class="paper-default-text-size" id="paper-default-text-size-wrap">ขนาดข้อความใหม่ <input id="paper-default-text-size" type="number" min="10" max="96" step="1" value="24" aria-label="ขนาดข้อความใหม่"></label><label class="paper-finger"><input id="paper-finger" type="checkbox">นิ้วเขียน</label><label class="paper-palm-guard" title="เมื่อเปิดจะไม่ใช้การแตะจากนิ้วบนกระดาษเพื่อซูมหรือสร้างข้อความ ใช้ Apple Pencil และปุ่มซูมได้ตามปกติ"><input id="paper-palm-guard" type="checkbox"> ✋ กันฝ่ามือ / ล็อกซูม</label></div></details><button type="button" data-paper="pages" class="paper-pages-toggle" aria-controls="paper-pages-sidebar" aria-expanded="false" aria-label="แสดงรายการหน้ากระดาษ">▤ หน้า</button></div>
 <div class="paper-quickbar" id="paper-quickbar" role="toolbar" aria-label="เครื่องมือปรับแต่งปากกาและรูปทรง">
  <span class="paper-quickbar-title">เครื่องมือ</span>
  <div class="paper-quick-colors" role="group" aria-label="เลือกสี">${colors.map(c=>`<button type="button" data-quick-color="${c}" style="--ink:${c}" aria-label="สี ${c}" title="เลือกสี ${c}"></button>`).join('')}</div>
  <label class="paper-quick-linewidth" id="paper-quick-linewidth">ความหนา <input id="paper-quick-width" type="range" min="1" max="12" value="5" step="1" aria-label="ปรับความหนาเส้น"><output id="paper-quick-width-value" for="paper-quick-width">5</output></label>
  <label class="paper-quick-shape" id="paper-quick-shape-wrap">รูปทรง <select id="paper-quick-shape" aria-label="เลือกรูปทรง">${Object.entries(shapes).map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></label>
  <label class="paper-quick-line" id="paper-quick-line-wrap">ลักษณะเส้น <select id="paper-quick-line-style" aria-label="เลือกลักษณะเส้น">${Object.entries(lineStyles).map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></label>
  <label class="paper-quick-text" id="paper-quick-text-wrap">ขนาดข้อความ <input id="paper-quick-text-size" type="number" min="10" max="96" step="1" value="24" aria-label="ขนาดตัวอักษรสำหรับข้อความใหม่"></label>
  <button type="button" class="paper-quick-action" data-quick-action="ruler" aria-pressed="false" title="เปิดหรือปิดไม้บรรทัด">📏 ไม้บรรทัด</button>
  <button type="button" class="paper-quick-action" data-quick-action="multi" aria-pressed="false" title="เลือกวัตถุหลายชิ้น">เลือกหลายชิ้น</button>
 </div>
 <div class="paper-text-ribbon" id="paper-text-ribbon" role="toolbar" aria-label="หน้าแรก — จัดรูปแบบข้อความคล้าย Microsoft Word" hidden>
  <strong class="paper-ribbon-title">หน้าแรก · ข้อความ</strong>
  <label class="paper-ribbon-size">ขนาด <button type="button" data-word-step="-1" aria-label="ลดขนาดตัวอักษร">−</button><input id="paper-word-size" type="number" min="10" max="96" step="1" value="24" inputmode="numeric" aria-label="ขนาดตัวอักษรที่เลือก"><button type="button" data-word-step="1" aria-label="เพิ่มขนาดตัวอักษร">＋</button></label>
  <div class="paper-ribbon-format" role="group" aria-label="รูปแบบตัวอักษร">
   <button type="button" data-word-format="bold" aria-label="ตัวหนา" aria-pressed="false" title="ตัวหนา Ctrl+B"><b>B</b></button>
   <button type="button" data-word-format="italic" aria-label="ตัวเอียง" aria-pressed="false" title="ตัวเอียง Ctrl+I"><em>I</em></button>
   <button type="button" data-word-format="underline" aria-label="ขีดเส้นใต้" aria-pressed="false" title="ขีดเส้นใต้ Ctrl+U"><u>U</u></button>
   <button type="button" data-word-format="strike" aria-label="ขีดฆ่าข้อความ" aria-pressed="false" title="ขีดฆ่าข้อความ"><s>S</s></button>
  </div>
  <div class="paper-ribbon-colors" role="group" aria-label="เลือกสีตัวอักษรเฉพาะคำ">
   <span>สีตัวอักษร</span>
   ${colors.map(c=>`<button type="button" class="paper-word-swatch" data-word-color="${c}" style="--word-ink:${c}" title="เปลี่ยนข้อความที่เลือกเป็นสี ${c}" aria-label="เปลี่ยนเฉพาะคำเป็นสี ${c}" aria-pressed="false"></button>`).join('')}
   <label class="paper-word-custom" title="เลือกสีตัวอักษรเพิ่มเติม">สีอื่น <input id="paper-word-custom-color" type="color" value="#172033" aria-label="เลือกสีตัวอักษรอื่น"></label>
  </div>
  <button type="button" data-paper="word-link" class="paper-ribbon-link" title="เลือกคำเพื่อแนบเว็บไซต์หรือไฟล์">🔗 ลิงก์ / ไฟล์เฉพาะคำ</button>
  <button type="button" data-paper="finish-text" class="paper-ribbon-done">✓ เสร็จสิ้น</button>
  <small class="paper-ribbon-help">ลากเลือกเฉพาะคำ แล้วกด B, I, U, สี หรือ ลิงก์</small>
 </div>
 <div id="paper-word-menu" class="paper-word-menu" role="toolbar" aria-label="เมนูคลิกขวาจัดรูปแบบข้อความ" hidden>
   <div class="paper-word-menu-heading"><strong>จัดรูปแบบข้อความที่เลือก</strong><button type="button" data-word-menu-close aria-label="ปิดเมนู">×</button></div>
   <div class="paper-word-menu-tools" role="group" aria-label="ตัวหนา ตัวเอียง ขีดเส้นใต้">
    <button type="button" data-word-menu-format="bold" title="ตัวหนา"><b>B</b></button>
    <button type="button" data-word-menu-format="italic" title="ตัวเอียง"><i>I</i></button>
    <button type="button" data-word-menu-format="underline" title="ขีดเส้นใต้"><u>U</u></button>
    <button type="button" data-word-menu-format="strike" title="ขีดฆ่า"><s>S</s></button>
    <label>ขนาด <input id="paper-word-menu-size" type="number" min="10" max="96" step="1" inputmode="numeric" aria-label="ขนาดข้อความที่เลือก"></label>
   </div>
   <div class="paper-word-menu-colors" role="group" aria-label="สีตัวอักษร">
    <span>สี</span>
    ${colors.map(c=>`<button type="button" data-word-menu-color="${c}" style="--word-ink:${c}" aria-label="สี ${c}"></button>`).join('')}
    <label>สีอื่น <input id="paper-word-menu-custom" type="color" value="#172033" aria-label="เลือกสีเพิ่มเติม"></label>
   </div>
   <div class="paper-word-menu-actions">
    <button type="button" data-word-menu-copy>คัดลอก</button>
    <button type="button" data-word-menu-link>🔗 ลิงก์ / ไฟล์เฉพาะคำ</button>
   </div>
 </div>
 <div class="paper-workspace"><aside class="paper-pages" id="paper-pages-sidebar" aria-label="รายการหน้ากระดาษ"><div class="paper-pages-heading"><b>หน้ากระดาษ</b><button data-paper="add-page" aria-label="เพิ่มหน้า">＋</button></div><div id="paper-page-list"></div><button data-paper="add-page" class="paper-add-page">＋ เพิ่มหน้า</button></aside><div class="paper-center"><div class="paper-context"><label>กระดาษ <select id="paper-template"><option value="plain">ว่าง</option><option value="ruled">เส้นบรรทัด</option><option value="grid">ตาราง</option><option value="dots">จุด</option></select></label><div class="paper-context-actions"><button data-paper="duplicate-page" title="ทำสำเนาหน้า">ทำสำเนา</button><button data-paper="delete-page">ลบหน้า</button><button data-paper="files" title="แนบ PDF, Word หรือ PowerPoint">แนบไฟล์</button><button data-paper="info">รายละเอียด</button></div></div><div id="paper-viewport" class="paper-viewport"><div id="paper-wrap" class="paper-wrap"><div id="paper-sheet" class="paper-sheet"><svg id="paper-svg" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 1273" role="img" aria-label="หน้ากระดาษสำหรับเขียน พิมพ์ และวางรูป"></svg><textarea id="paper-text-input" hidden aria-label="แก้ข้อความบนกระดาษ และใช้ Apple Pencil เขียนต่อในช่องเดิม" spellcheck="false"></textarea></div></div></div><div class="paper-bottom"><span id="paper-page-label">กำลังเปิดสมุด…</span><span id="paper-hint" role="status">แตะบนกระดาษเพื่อพิมพ์ · แตะรูปเพื่อย้ายหรือปรับขนาด</span><div><button data-paper="zoom-out" aria-label="ย่อกระดาษ">−</button><button data-paper="fit" id="paper-zoom">พอดีหน้า</button><button data-paper="zoom-in" aria-label="ขยายกระดาษ">＋</button></div></div></div></div>
 <div id="paper-mobile-editor" class="paper-mobile-editor" hidden><div class="paper-mobile-editor-top"><strong>✎ แก้ไขข้อความ</strong><div class="paper-mobile-editor-actions"></div></div><p>แก้ไขในช่องนี้เพื่อให้อ่านชัดขณะพิมพ์</p></div>
  <div id="paper-selection-tools" class="paper-selection-tools" hidden><span>เลือกแล้ว <b id="paper-selected-count"></b></span><div class="paper-shape-selection" id="paper-shape-selection" hidden><label>รูปทรง <select id="paper-selected-shape" aria-label="เปลี่ยนรูปทรงที่เลือก">${Object.entries(shapes).map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></label><label>เส้น <select id="paper-selected-line-style" aria-label="เปลี่ยนรูปแบบเส้นของรูปทรงที่เลือก">${Object.entries(lineStyles).map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></label></div><button data-paper="edit-text">แก้ข้อความ</button><label>ขนาดทั้งกล่อง <input id="paper-font-size" type="number" min="10" max="96" step="1" value="24" aria-label="ขนาดตัวอักษรทั้งกล่อง"></label><button data-paper="bold">ตัวหนา</button><button data-paper="image-link" hidden>ใส่ลิงก์</button><a id="paper-open-link" hidden target="_blank" rel="noopener noreferrer">เปิดลิงก์ ↗</a><button data-paper="crop" hidden>ครอปรูป</button><button data-paper="duplicate">ทำสำเนา</button><button data-paper="delete-object" class="paper-danger">ลบที่เลือก</button></div>
 <aside id="paper-info" class="paper-info" hidden><div><h2>รายละเอียดโน้ต</h2><button data-paper="info">ปิด</button></div><label>วิชา<input id="paper-course" value="${esc(n.course)}" placeholder="POL1101"></label><label>ประเภทโน้ต<select id="paper-source">${Object.entries(NOTE_SOURCES).map(([k,v])=>`<option value="${k}" ${k===noteSource(n)?"selected":""}>${v}</option>`).join("")}</select></label><label>แท็ก<input id="paper-tags" maxlength="250" value="${esc(n.tags)}"></label><label>คำถามทบทวน<textarea id="paper-question" maxlength="4000">${esc(n.question)}</textarea></label><label>คำตอบ<textarea id="paper-answer" maxlength="10000">${esc(n.answer)}</textarea></label><p>หน้ากระดาษเดียวกันทุกเครื่อง ไม่ต้องล็อกอิน</p><a href="#account">ข้อมูลและการซิงก์ →</a></aside><dialog id="paper-link-dialog" class="paper-sheet-dialog"><form method="dialog"><h2>ลิงก์ของรูปภาพ</h2><label>เว็บไซต์<input name="url" type="url" maxlength="2048" placeholder="https://…" autofocus></label><p role="status"></p><div class="paper-dialog-actions"><button value="save">บันทึกลิงก์</button><button value="remove" formnovalidate>ลบลิงก์</button><button value="cancel" formnovalidate>ยกเลิก</button></div></form></dialog><dialog id="paper-files" class="paper-sheet-dialog"><header><h2>ไฟล์แนบ</h2><form method="dialog"><button>ปิด</button></form></header><ul id="paper-file-list"></ul><label>แนบ PDF, Word หรือ PowerPoint (ไม่เกิน 2 MB ต่อไฟล์)<input type="file" id="paper-doc-file" accept=".pdf,.doc,.docx,.ppt,.pptx"></label><p id="paper-file-status" role="status"></p></dialog><input id="paper-image-file" hidden type="file" accept="image/png,image/jpeg,image/webp,image/gif" multiple></section>`;}
